const { validarResumenBoletin } = require('@healthradar/core');
const pend = $('Postgres - Obtener pendiente').item.json;
const output = $input.first().json.output;
// Modelo que respondio (solo para nombrar la fuente en los mensajes de error)
let agente = 1;
try { if ($('AI Agent Gemini 3').isExecuted) agente = 3; else if ($('AI Agent Gemini 2').isExecuted) agente = 2; } catch (e) {}
const NODO_MODELO = { 1: 'Google Gemini Chat Model', 2: 'Google Gemini Chat Model 2', 3: 'Google Gemini Chat Model 3' };
let modelo = 'gemini';
try { modelo = String($node[NODO_MODELO[agente]].parameter.modelName).replace(/^models\//, ''); } catch (e) {}
const validado = validarResumenBoletin(output, modelo, pend.semana_epidemiologica, {
  semanaPrevia: pend.semana_previa,
  resumenPrevio: pend.resumen_previo,
  // exigirCifras: true,   // activar cuando SYSTEM_PROMPT_FASE_B ya pida la linea [CIFRAS: ...]
});
return [{
  json: {
    id_boletin: pend.id_boletin,
    anio: pend.anio,
    semana_epidemiologica: pend.semana_epidemiologica,
    resumen: validado.resumen,
    procesado: true
  }
}];

