// Sprint 3 (ADR-012): la regla DGE vive en @healthradar/core (calcularRangoFechasSemana).
const { calcularRangoFechasSemana } = require('@healthradar/core');
return [{ json: calcularRangoFechasSemana($json.anio, $json.semana_epidemiologica) }];

// Sprint 3 (ADR-012): la agregacion semanal vive en @healthradar/core (agruparPorSemanaEpi).
// Sin datos → null (nunca NaN ni 0). Valida que los 7 dias sean justo la semana pedida.
const { agruparPorSemanaEpi } = require('@healthradar/core');
const datos = $('Split In Batches (departamentos)').item.json;
const semana = agruparPorSemanaEpi($input.first().json.daily).find(
  s => s.anio === Number(datos.anio) && s.semana === Number(datos.semana_epidemiologica));
if (!semana) throw new Error(`Open-Meteo no devolvio la semana completa ${datos.anio}-S${datos.semana_epidemiologica} para ${datos.departamento}`);
return [{ json: {
  latitud: datos.latitud, longitud: datos.longitud,
  anio: datos.anio, semana_epidemiologica: datos.semana_epidemiologica,
  temp_max_promedio: semana.temp_max_promedio, temp_min_promedio: semana.temp_min_promedio,
  temp_mean_promedio: semana.temp_mean_promedio, precipitacion_total: semana.precipitacion_total,
  humedad_promedio: semana.humedad_promedio,
} }];

// Sprint 3 (ADR-012): los 25 puntos (Callao y Lima separados) viven en @healthradar/core.
const { generarDepartamentos } = require('@healthradar/core');
return generarDepartamentos($input.first().json).map(json => ({ json }));

// HU-2 (Phoenix): marca la hora de inicio de la cadena LLM (resumen del boletin) para medir latencia.
// Solo agrega _t0; el prompt sigue leyendo $json.text.
// Falla claro si falta el prompt externalizado (evita que el modelo responda sin instrucciones).
if (!$env.SYSTEM_PROMPT_FASE_B) throw new Error('Falta SYSTEM_PROMPT_FASE_B en infrastructure/.env (ver src/ia-ops/prompts)');
return $input.all().map((i, idx) => ({ json: { ...i.json, _t0: Date.now() }, pairedItem: idx }));

const { construirTrazaPhoenix } = require('@healthradar/core');
// HU-2 (Phoenix): span del resumen de boletin generado y validado.
const pend = $('Postgres - Obtener pendiente').first().json;
let inicio; try { inicio = $('Marcar inicio (traza)').first().json._t0; } catch (e) {}
// Cadena de failover: ultimo agente que se ejecuto = el que respondio (1, 2 o 3)
let agente = 1;
try { if ($('AI Agent Gemini 3').isExecuted) agente = 3; else if ($('AI Agent Gemini 2').isExecuted) agente = 2; } catch (e) {}
let promptChars = 0;
try { promptChars = String($('Extract from File').first().json.text || '').length; } catch (e) {}
// El PDF completo es enorme: en la traza va una referencia al boletin, no el texto entero.
const entrada = `Resumir boletin ${pend.id_boletin} (SE ${pend.semana_epidemiologica}, ${pend.anio}) ${pend.url_boletin || ''}`.trim();
const NODO_MODELO = { 1: 'Google Gemini Chat Model', 2: 'Google Gemini Chat Model 2', 3: 'Google Gemini Chat Model 3' };
let modelo = 'gemini';
try { modelo = String($node[NODO_MODELO[agente]].parameter.modelName).replace(/^models\//, ''); } catch (e) {}
const base = { nombre: 'boletin.resumen', entrada, modelo, inicioMs: inicio, finMs: Date.now(),
  sessionId: 'healthradar-faseb', promptChars,
  metadatos: { flujo: 'Fase B', proveedor: 'google', agente, id_boletin: pend.id_boletin, anio: pend.anio, semana: pend.semana_epidemiologica } };
const r = $input.first().json;
const traza = construirTrazaPhoenix({ ...base, salida: r.resumen, exito: !!r.resumen, error: r.resumen ? '' : 'Resumen vacio' });
return [{ json: { traza } }];

